SELECT id, account_id, username, password_hash, display_name, email, mobile, status, deleted, create_time, update_time FROM rbac_user WHERE account_id = #{accountId} AND deleted = 0
AND username LIKE CONCAT('%', #{username}, '%')
AND status = #{status}
ORDER BY id DESC LIMIT #{offset}, #{pageSize}
